import hashlib
import math

class BloomFilter:
    """
    A Bloom Filter implementation for probabilistic membership testing.

    The Bloom Filter is initialized with the expected number of items and the desired false positive rate.
    The optimal size of the bit array and the number of hash functions are calculated based on these parameters.
    Items can be added to the filter, and membership tests can be performed.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        if expected_items <= 0:
            raise ValueError("Expected items must be positive")
        if not (0 < false_positive_rate < 1):
            raise ValueError("False positive rate must be between 0 and 1")

        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        self.bit_array_size = self._calculate_bit_array_size(expected_items, false_positive_rate)
        self.num_hashes = self._calculate_num_hashes(self.bit_array_size, expected_items)

        self.bit_array = [0] * self.bit_array_size

    def _calculate_bit_array_size(self, n: int, p: float) -> int:
        """Calculates the optimal size of the bit array."""
        m = - (n * math.log(p)) / (math.log(2) ** 2)
        return math.ceil(m)

    def _calculate_num_hashes(self, m: int, n: int) -> int:
        """Calculates the optimal number of hash functions."""
        k = (m / n) * math.log(2)
        return math.ceil(k)

    def _hashes(self, item: str):
        """Generates multiple hash values for the given item."""
        hash_results = set()
        for i in range(self.num_hashes):
            hash_value = hashlib.md5(f"{item}{i}".encode()).hexdigest()
            hash_results.add(int(hash_value, 16) % self.bit_array_size)
        return hash_results

    def add(self, item: str) -> None:
        """Adds an item to the Bloom Filter."""
        for index in self._hashes(item):
            self.bit_array[index] = 1

    def contains(self, item: str) -> bool:
        """Checks if the item is possibly in the Bloom Filter."""
        return all(self.bit_array[index] for index in self._hashes(item))

